export interface InstinctObservation {
  id: string;
  sessionId: string;
  pattern: string;
  weight: number;
  observedAt: number;
}

export interface InstinctPromotion {
  observationId: string;
  promotedAt: number;
  toSkillId: string;
}

export interface LearningLoopConfig {
  promotionThreshold: number;
  observationWindowMs: number;
}

const DEFAULT_CONFIG: LearningLoopConfig = {
  promotionThreshold: 3,
  observationWindowMs: 7 * 86400000,
};

export class LearningLoop {
  private observations: InstinctObservation[] = [];
  private promotions: InstinctPromotion[] = [];

  constructor(private readonly config: LearningLoopConfig = DEFAULT_CONFIG) {}

  observe(o: InstinctObservation): void {
    this.observations.push(o);
  }

  candidates(now: number = Date.now()): InstinctObservation[] {
    const cutoff = now - this.config.observationWindowMs;
    const recent = this.observations.filter((o) => o.observedAt >= cutoff);
    const byPattern = new Map<string, InstinctObservation[]>();
    for (const o of recent) {
      const arr = byPattern.get(o.pattern) ?? [];
      arr.push(o);
      byPattern.set(o.pattern, arr);
    }
    const out: InstinctObservation[] = [];
    for (const [, group] of byPattern) {
      if (group.length >= this.config.promotionThreshold) {
        const top = group.reduce((a, b) => (a.weight >= b.weight ? a : b));
        out.push(top);
      }
    }
    return out;
  }

  promote(observationId: string, toSkillId: string, now: number = Date.now()) {
    const p: InstinctPromotion = {
      observationId,
      promotedAt: now,
      toSkillId,
    };
    this.promotions.push(p);
    return p;
  }

  getPromotions(): readonly InstinctPromotion[] {
    return this.promotions;
  }
}
